static inline const char * hit_bitmap_tostring(unsigned int element){

	static char buffer[(sizeof(unsigned int) * (size_t) 8)+1];
	buffer[(sizeof(unsigned int) * (size_t) 8)] = '\0';

	unsigned int mask = (((unsigned int) 1) << ((sizeof(unsigned int) * (size_t) 8)-1));
	unsigned int i;
	for(i=0;i<(sizeof(unsigned int) * (size_t) 8);i++){

		if( (mask & element) == 0 ){
			buffer[i] = '0';
		} else{
			buffer[i] = '1';
		}
		mask = mask >> 1;
	}
	return buffer;
}


 






 
