	do{
		var++;
		if(var == (((shape). info . bitmap). cards[(1)])){
			
			break;
		}
	} while(((((shape). info . bitmap). data)[(((size_t)((vertex)*(((shape). info . bitmap). cards[(1)])+(var)))/(sizeof(unsigned int) * (size_t) 8))] & (((((unsigned int) 1) << ((sizeof(unsigned int) * (size_t) 8)-1))) >> (((size_t)((vertex)*(((shape). info . bitmap). cards[(1)])+(var)))%(sizeof(unsigned int) * (size_t) 8))))==0);

	
