static inline HitKTile hit_ktile( void *refP ) {
	HitKTile	result;
	HitTile		*ref = (HitTile *)refP;
	result.kdata = (float *)ref->devData;
	result.jump[0] = ref->origAcumCard[1];
	result.jump[1] = ref->origAcumCard[2];
	result.jump[2] = ref->origAcumCard[3];
	result.dimx = ((*ref). card[0]);
	result.dimy = ((*ref). card[1]);
	result.dimz = ((*ref). card[2]);
	return result;
}







































 



































   
