void init_arrays(HitTile_float u1, HitTile_float u2, HitTile_float v1, HitTile_float v2,
                HitTile_float w, HitTile_float x, HitTile_float y, HitTile_float z,
                HitTile_float A, int size)
{
    int i, j;

    
    for (i = 0; i < size; i++) {
        ((u1). data[(i)*(u1). qstride[0]]) = i;
        ((u2). data[(i)*(u2). qstride[0]]) = ((i+1)/size)/2.0;
        ((v1). data[(i)*(v1). qstride[0]]) = ((i+1)/size)/4.0;
        ((v2). data[(i)*(v2). qstride[0]]) = ((i+1)/size)/6.0;
        ((y). data[(i)*(y). qstride[0]])  = ((i+1)/size)/8.0;
        ((z). data[(i)*(z). qstride[0]])  = ((i+1)/size)/9.0;
        ((x). data[(i)*(x). qstride[0]])  = 0.0;
        ((w). data[(i)*(w). qstride[0]])  = 0.0;
        for (j = 0; j < size; j++) {
            ((A). data[(i)*(A). qstride[0]*(A). origAcumCard[1]+(j)*(A). qstride[1]]) = ((float) i*j)/size;
        }
    }
}

